INSERT INTO "events" VALUES('evt_interstellar_imax','Interstellar (10th Anniversary IMAX 70mm)','Interstellar (10th Anniversary IMAX 70mm)','Prasad IMAX Auditorium 1, Screen 1','Today • 08:30 PM (Dolby Atmos & Laser Projection)','movie','Sci-Fi • Epic Drama • Adventure','2h 49m',9.8,'2.1M votes','English (Dolby Atmos)','IMAX 70mm Laser','https://images.unsplash.com/photo-1534447677768-be436bb09401?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=1600&auto=format&fit=crop&q=80','A team of explorers travel through a wormhole in space in an attempt to ensure humanity''s survival. Experience Christopher Nolan''s visual triumph in uncompressed 70mm IMAX format with heart-thumping audio.',450.0,'{"cast":["Matthew McConaughey","Anne Hathaway","Jessica Chastain","Michael Caine"],"director":"Christopher Nolan","venues":[{"id":"v1","name":"Prasad IMAX Screen 1","location":"Central Dome, IMAX Laser 4K","formats":["IMAX 70mm","Dolby Atmos"],"features":["Laser Projection","Curved Screen","Recliners"]},{"id":"v2","name":"PVR Director''s Cut: Gold Class","location":"Palladium Mall, Audi 3","formats":["Dolby Cinema","Atmos"],"features":["Butler on Call","Gourmet Dining","Plush Recliners"]},{"id":"v3","name":"Cinépolis VIP Lounge","location":"Grand Galleria, Screen 5","formats":["4DX","RealD 3D"],"features":["Motion Chairs","Environmental FX"]}],"dates":["Today (22 Sep)","Tomorrow (23 Sep)","Wed (24 Sep)","Thu (25 Sep)","Fri (26 Sep)"],"showtimes":["10:30 AM","02:15 PM","06:30 PM","08:30 PM","10:45 PM"]}');
INSERT INTO "events" VALUES('evt_dune_two','Dune: Part Two (IMAX Experience)','Dune: Part Two (IMAX Experience)','PVR Director''s Cut Audi 2','Today • 07:15 PM (IMAX Laser & Spatial Audio)','movie','Action • Sci-Fi • Adventure','2h 46m',9.6,'980K votes','English / IMAX Laser','IMAX 4DX 3D','https://images.unsplash.com/photo-1509198397868-475647b2a1e5?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=1600&auto=format&fit=crop&q=80','Paul Atreides unites with Chani and the Fremen while seeking revenge against the conspirators who destroyed his family. Masterpiece directed by Denis Villeneuve.',480.0,'{"cast":["Timothée Chalamet","Zendaya","Rebecca Ferguson","Javier Bardem"],"director":"Denis Villeneuve","venues":[{"id":"v1","name":"Prasad IMAX Screen 1","location":"Central Dome","formats":["IMAX Laser"],"features":["Dolby Atmos","Curved Giant Screen"]},{"id":"v2","name":"PVR Director''s Cut: Gold Class","location":"Audi 2","formats":["Dolby Atmos"],"features":["Gourmet Food","Recliners"]},{"id":"v4","name":"INOX Megaplex Laser","location":"Downtown Hub","formats":["Dolby Atmos","Laser 4K"],"features":["Laser Sound","Spacious Seating"]}],"dates":["Today (22 Sep)","Tomorrow (23 Sep)","Wed (24 Sep)","Thu (25 Sep)"],"showtimes":["11:00 AM","03:30 PM","07:15 PM","09:45 PM","11:15 PM"]}');
INSERT INTO "events" VALUES('evt_deadpool_wolverine','Deadpool & Wolverine','Deadpool & Wolverine','Cinépolis VIP Grand Screen 4','Today • 09:00 PM (Dolby Cinema 3D)','movie','Action • Comedy • Sci-Fi','2h 08m',9.3,'840K votes','English / Hindi (Dolby Cinema)','3D Dolby Vision','https://images.unsplash.com/photo-1563089145-599997674d42?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1579546929518-9e396f3cc809?w=1600&auto=format&fit=crop&q=80','Wolverine is recovering from his injuries when he crosses paths with the loudmouth Deadpool. They team up to defeat a common enemy in the Marvel cinematic multiverse.',420.0,'{"cast":["Ryan Reynolds","Hugh Jackman","Emma Corrin","Matthew Macfadyen"],"director":"Shawn Levy","venues":[{"id":"v3","name":"Cinépolis VIP Grand Screen 4","location":"Grand Galleria","formats":["3D Dolby Cinema"],"features":["Laser 3D","Dolby Atmos"]},{"id":"v1","name":"Prasad IMAX Laser","location":"Screen 2","formats":["IMAX 3D"],"features":["Laser Screen"]},{"id":"v2","name":"PVR Gold Class","location":"Audi 4","formats":["Dolby Atmos"],"features":["Luxury Recliners"]}],"dates":["Today (22 Sep)","Tomorrow (23 Sep)","Wed (24 Sep)","Thu (25 Sep)","Fri (26 Sep)"],"showtimes":["12:15 PM","04:00 PM","06:45 PM","09:00 PM","11:30 PM"]}');
INSERT INTO "events" VALUES('evt_coldplay_tour','Coldplay: Music of the Spheres World Tour','Coldplay: Music of the Spheres World Tour','District Arena & Stadium Amphitheatre','Saturday • 07:00 PM (Mega Live Concert)','concert','Live Concert • Pop Rock • Stadium Arena','3h 00m',9.9,'500K fans','Live Performance','Stadium Experience','https://images.unsplash.com/photo-1470225620780-dba8ba36b745?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=1600&auto=format&fit=crop&q=80','Global sensation Coldplay brings their breathtaking stadium concert featuring LED wristbands, cosmic visuals, pyro, and legendary anthems like Yellow, Fix You, and Viva La Vida.',950.0,'{"cast":["Chris Martin","Jonny Buckland","Guy Berryman","Will Champion"],"director":"Coldplay Live Productions","venues":[{"id":"v_arena","name":"District Arena Main Stage","location":"Olympic Stadium Zone","formats":["Live Sound System"],"features":["LED Wristband Included","Laser Pyrotechnics","VIP Lounge Access"]},{"id":"v_bowl","name":"Sunset Open Air Amphitheatre","location":"South Arena","formats":["Dolby Live Acoustic"],"features":["Grandstand Views","Festival Village"]}],"dates":["Saturday (27 Sep)","Sunday (28 Sep)"],"showtimes":["06:30 PM","07:00 PM","08:00 PM"]}');
INSERT INTO "events" VALUES('evt_oppenheimer_70mm','Oppenheimer (70mm Special Screening)','Oppenheimer (70mm Special Screening)','Prasad IMAX Screen 2','Tomorrow • 05:30 PM (70mm Master Print)','movie','Biography • Drama • History','3h 00m',9.5,'1.4M votes','English (70mm 6-Track Sound)','70mm Large Format','https://images.unsplash.com/photo-1440404653325-ab127d49abc1?w=800&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1446776811953-b23d57bd21aa?w=1600&auto=format&fit=crop&q=80','The story of American scientist J. Robert Oppenheimer and his role in the development of the atomic bomb during the Manhattan Project.',460.0,'{"cast":["Cillian Murphy","Emily Blunt","Matt Damon","Robert Downey Jr."],"director":"Christopher Nolan","venues":[{"id":"v1","name":"Prasad IMAX Screen 1","location":"Central Dome","formats":["70mm Film"],"features":["Full Height IMAX Aspect Ratio"]},{"id":"v2","name":"PVR Gold Class","location":"Audi 1","formats":["Dolby Atmos"],"features":["Plush Recliners"]}],"dates":["Tomorrow (23 Sep)","Wed (24 Sep)","Thu (25 Sep)"],"showtimes":["01:30 PM","05:30 PM","09:15 PM"]}');
